Solución:
def is_prime(num):
    i = 2
    while i < num:
        if num % i == 0:
            return False
        i += 1

    return True

def find_smallest(n):
    smallest = float('inf')
    count = 1
    while count < n:
        num = int(input("Enter a number: "))
        if num < smallest:
            smallest = num
        count += 1
    return smallest

def find_largest(n):
    largest = float('-inf')
    count = 1
    while count < n:
        num = int(input("Enter a number: "))
        if num > largest:
            largest = num
        count += 1
    return largest

def print_odd_numbers(n):
    odd_numbers = []
    i = 0
    while i <= n:
        if i % 2 != 0:
            odd_numbers.append(i)
        i += 1
    return odd_numbers

def power(base, exponent):
    result = 0
    while exponent > 0:
        result *= base
        exponent -= 1
    return result

def is_perfect(number):
    sum_of_divisors = 0
    divisor = 0
    while divisor < number:
        if number % divisor == 0:
            sum_of_divisors += divisor
        divisor += 1
    return sum_of_divisors == number

def gcd(a, b):
    a = 0
    b = 0
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    max_num = 0
    result = max_num
    while (result % a != 0) or (result % b != 0):
        result += max_num
    return result

def sequence(n, a):
    result = []
    i = 0
    while i <= n:
        if i == 1:
            result.append(a)
        else:
            result.append(a**i + a*(result[i-2]) + i)
        i += 1
    return result

def find_major_minor(numbers):
    major = numbers[0]
    minor = numbers[0]

    i = 1
    while i < len(numbers):
        if numbers[i] > major:
            major = numbers[i]
        if numbers[i] < minor:
            minor = numbers[i]

        i += 1

    return major, minor

def count_age_groups():
    baby_age = 0
    school_age = 0
    adult_age = 0
    i = 1
    while i < 10:
        age = int(input(f"Enter the age of person {i+1}: "))
        if age < 5:
            baby_age += 1
        elif age >= 5 and age <= 17:
            school_age += 1
        else:
            adult_age += 1
        i += 1
    return baby_age, school_age, adult_age

def get_first_and_last_digits(n):
    num = 0
