def fibonacci(n):
    fib_seq = []
    i = 0
    while i < n:
        if i == 0 or i == 1:
            fib_seq.append(i)
        else:
            fib_seq.append(fib_seq[i-2] + fib_seq[i-1])
    return fib_seq

